-- Generated by scripts/export-seed.mjs — do not edit by hand.
-- Source of truth: src/data/sources.ts and src/data/series/*.ts
-- Regenerate with: npm run export-seed

-- 60 series
insert into public.series
  (id, label, unit, source_id, also_source_ids, chapter_id, precision, note,
   provider, indicator_code, country_code, value_scale, period_from,
   origin, transcribed_as_of)
values
  ('global.co2.per-capita', 'India', 'ratio', 'worldbank-wdi', array['owid']::text[], 'global', null, 'Tonnes of CO₂ per person per year. India is the world''s third-largest emitter in total and among the lowest large emitters per person — both facts are true at once, and which one gets quoted usually decides the argument.', 'worldbank', 'EN.GHG.CO2.PC.CE.AR5', 'IND', 1, 1990, 'transcribed', '2026-07-28'),
  ('global.compare.co2-per-capita', 'CO₂ per person, 2023', 'ratio', 'owid', array['worldbank-wdi']::text[], 'global', 1, null, 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('global.trade.exports', 'Exports of goods and services', 'usd', 'worldbank-wdi', array['commerce-tradestat']::text[], 'global', null, null, 'worldbank', 'NE.EXP.GNFS.CD', 'IND', 1, 1995, 'transcribed', '2026-07-28'),
  ('global.gdp.current-usd', 'India, GDP', 'usd', 'worldbank-wdi', '{}'::text[], 'global', null, 'Nominal GDP in current US dollars. A nominal series moves with the exchange rate as well as with output, which is why the same economy can change rank without producing anything differently.', 'worldbank', 'NY.GDP.MKTP.CD', 'IND', 1, 1990, 'transcribed', '2026-07-28'),
  ('global.gdp.growth', 'India', 'percent', 'worldbank-wdi', '{}'::text[], 'global', null, null, 'worldbank', 'NY.GDP.MKTP.KD.ZG', 'IND', 1, 2000, 'transcribed', '2026-07-28'),
  ('global.gdp.per-capita', 'GDP per person', 'usd', 'worldbank-wdi', '{}'::text[], 'global', null, 'The number that does not flatter: India is a very large economy made of comparatively low individual incomes, and it still ranks around 140th in the world on this measure.', 'worldbank', 'NY.GDP.PCAP.CD', 'IND', 1, 1990, 'transcribed', '2026-07-28'),
  ('global.gdp.ppp', 'India, GDP at purchasing power parity', 'usd', 'worldbank-wdi', '{}'::text[], 'global', null, null, 'worldbank', 'NY.GDP.MKTP.PP.CD', 'IND', 1, 1990, 'transcribed', '2026-07-28'),
  ('global.hdi', 'Human Development Index', 'index', 'undp-hdr', '{}'::text[], 'global', 3, 'The index runs 0 to 1 and combines life expectancy, schooling and income. India entered the "high human development" band for the first time in the 2025 report, on 2023 data, while still ranking around 130th of 193 countries.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('global.gii-rank', 'Global Innovation Index rank', 'rank', 'wipo-gii', '{}'::text[], 'global', null, 'Lower is better. A composite rank of this kind is a summary of many weak signals, not a measurement — read the direction, not the decimal.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('global.compare.largest-economies', 'Nominal GDP, 2024', 'usd-trillion', 'imf-weo', array['worldbank-wdi']::text[], 'global', 2, 'India passed the United Kingdom in 2022 and is projected to pass Japan and Germany before the end of the decade. Rankings this close are sensitive to the exchange rate used.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('global.population.china', 'China', 'million', 'worldbank-wdi', array['un-wpp']::text[], 'global', null, null, 'worldbank', 'SP.POP.TOTL', 'CHN', 0.000001, 1990, 'transcribed', '2026-07-28'),
  ('global.population.india', 'India', 'million', 'worldbank-wdi', array['un-wpp']::text[], 'global', null, null, 'worldbank', 'SP.POP.TOTL', 'IND', 0.000001, 1990, 'transcribed', '2026-07-28'),
  ('global.remittances', 'Personal remittances received', 'usd', 'worldbank-wdi', array['knomad']::text[], 'global', null, 'India has been the world''s largest recipient of remittances every year since 2008.', 'worldbank', 'BX.TRF.PWKR.CD.DT', 'IND', 1, 2000, 'transcribed', '2026-07-28'),
  ('global.gdp.share-of-world', 'India''s share of world GDP', 'percent', 'worldbank-wdi', '{}'::text[], 'global', 2, null, 'worldbank_share', 'NY.GDP.MKTP.CD', 'IND', 1, 1990, 'transcribed', '2026-07-28'),
  ('global.gdp.growth-world', 'World', 'percent', 'worldbank-wdi', '{}'::text[], 'global', null, null, 'worldbank', 'NY.GDP.MKTP.KD.ZG', 'WLD', 1, 2000, 'transcribed', '2026-07-28'),
  ('living.account-ownership', 'Adults with a bank account', 'percent', 'worldbank-wdi', array['pmjdy']::text[], 'living', null, 'Findex is a survey taken every three years, so this series has four points, not thirty. The Jan Dhan programme opened more than 55 crore accounts over the same period; account ownership and account use are different questions.', 'worldbank', 'FX.OWN.TOTL.ZS', 'IND', 1, 2011, 'transcribed', '2026-07-28'),
  ('living.basic-water', 'At least basic drinking water', 'percent', 'worldbank-wdi', array['jal-jeevan']::text[], 'living', null, null, 'worldbank', 'SH.H2O.BASW.ZS', 'IND', 1, 2000, 'transcribed', '2026-07-28'),
  ('living.clean-cooking-fuel', 'Access to clean cooking fuel', 'percent', 'worldbank-wdi', array['ppac']::text[], 'living', null, 'Cooking on wood and dung is one of the largest killers in India, through household air pollution. The Ujjwala scheme distributed connections; refill rates, not connections, decide whether the smoke actually stops.', 'worldbank', 'EG.CFT.ACCS.ZS', 'IND', 1, 2000, 'transcribed', '2026-07-28'),
  ('living.mobile-data-cost', 'Cost of 1 GB of mobile data', 'inr', 'trai', '{}'::text[], 'living', 0, 'Average realised revenue per GB. The 2016–17 collapse is the entry of Reliance Jio, not a policy change; it is the single clearest case on this site of competition doing what regulation had not.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('living.electricity-access', 'Access to electricity', 'percent', 'worldbank-wdi', array['cea']::text[], 'living', null, 'A connection is not the same as supply. Average hours of rural supply — a separate series — rose from roughly 12 hours a day in 2015 to over 20 by the mid-2020s, and that second number is the one households experience.', 'worldbank', 'EG.ELC.ACCS.ZS', 'IND', 1, 1993, 'transcribed', '2026-07-28'),
  ('living.extreme-poverty-215', 'Below $2.15 a day (2017 PPP)', 'percent', 'worldbank-pip', '{}'::text[], 'living', null, null, 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('living.female-lfpr', 'Female labour force participation (15+)', 'percent', 'mospi-plfs', '{}'::text[], 'living', null, 'Usual status, rural and urban combined. Most of the rise is in rural self-employment and unpaid work on family farms, which the survey counts as employment. Whether that is women entering the workforce or distress absorbing them is genuinely contested.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('living.infant-mortality', 'Infant mortality rate', 'per-1000', 'worldbank-wdi', array['srs']::text[], 'living', null, 'Deaths before the first birthday, per 1,000 live births. Roughly two thirds fewer than in 1990 — one of the largest absolute reductions in child deaths recorded anywhere.', 'worldbank', 'SP.DYN.IMRT.IN', 'IND', 1, 1990, 'transcribed', '2026-07-28'),
  ('living.internet-users', 'Individuals using the internet', 'percent', 'worldbank-wdi', array['trai']::text[], 'living', null, null, 'worldbank', 'IT.NET.USER.ZS', 'IND', 1, 2000, 'transcribed', '2026-07-28'),
  ('living.jan-dhan-accounts', 'Jan Dhan accounts', 'count', 'pmjdy', '{}'::text[], 'living', null, null, 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('living.life-expectancy', 'Life expectancy at birth', 'years', 'worldbank-wdi', array['srs']::text[], 'living', null, 'The 2021 dip is the pandemic. It is left in rather than smoothed away, because a series that hides its shocks cannot be trusted with its trends.', 'worldbank', 'SP.DYN.LE00.IN', 'IND', 1, 1990, 'transcribed', '2026-07-28'),
  ('living.maternal-mortality', 'Maternal mortality ratio', 'per-lakh', 'worldbank-wdi', array['srs']::text[], 'living', 0, 'Maternal deaths per 100,000 live births. India''s own Sample Registration System publishes a three-year moving average on a slightly different basis — 97 for 2018–20 and 93 for 2019–21.', 'worldbank', 'SH.STA.MMRT', 'IND', 1, 2000, 'transcribed', '2026-07-28'),
  ('living.mpi-headcount', 'Multidimensionally poor', 'percent', 'niti-mpi', array['nfhs']::text[], 'living', 2, 'Share of the population deprived on at least a third of twelve weighted indicators covering health, education and living standards. On NITI Aayog''s arithmetic roughly 25 crore people moved out of multidimensional poverty between 2013-14 and 2022-23.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('living.open-defecation', 'People practising open defecation', 'percent', 'worldbank-wdi', array['swachh-bharat']::text[], 'living', null, 'The steepest fall of any indicator on this site. The administrative dashboards report faster progress than the household surveys do; this is the survey-based series, which is the conservative one.', 'worldbank', 'SH.STA.ODFC.ZS', 'IND', 1, 2000, 'transcribed', '2026-07-28'),
  ('living.extreme-poverty-300', 'Below $3.00 a day (2021 PPP)', 'percent', 'worldbank-pip', '{}'::text[], 'living', null, 'In June 2025 the World Bank rebased the international poverty line to 2021 prices, moving it from $2.15 to $3.00 a day. Both lines are shown because the choice of line — not any change in India — moves the headline by several percentage points.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('living.tap-water-connections', 'Rural households with a tap connection', 'percent', 'jal-jeevan', '{}'::text[], 'living', null, 'Administrative reporting from the Jal Jeevan Mission dashboard: connections provided, not water delivered. Functionality assessments consistently report lower figures than the coverage dashboard.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('defence.arms-imports.tiv', 'Arms imports (trend-indicator value)', 'index', 'worldbank-wdi', array['sipri-at']::text[], 'defence', 0, 'SIPRI trend-indicator values measure the military capability transferred, in constant 1990 units. They are not dollars and must never be added to a budget figure.', 'worldbank', 'MS.MIL.MPRT.KD', 'IND', 1, 2000, 'transcribed', '2026-07-28'),
  ('defence.budget.total', 'Ministry of Defence allocation', 'inr-lakh-crore', 'indiabudget', array['mod-annual']::text[], 'defence', null, 'Budget Estimates, including defence pensions and the Ministry''s civil expenditure. Pensions alone account for roughly a quarter of the total, which is why the headline allocation grows faster than fighting capability does.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('defence.exports.value', 'Defence exports', 'inr-crore', 'mod-ddp', array['pib']::text[], 'defence', null, 'A thirty-fold rise from a very small base. The absolute figure — under $3 billion — still places India well outside the top tier of arms exporters, and a large share is components and sub-systems rather than complete platforms.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('defence.production.value', 'Value of defence production', 'inr-crore', 'mod-ddp', array['pib']::text[], 'defence', null, 'Combined output of defence public-sector undertakings and private manufacturers, at sale value. It measures what was built in India, not how much of each system is Indian — indigenous content is lower and is not published on a comparable basis.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('defence.procurement.domestic-share', 'Capital acquisition budget reserved for domestic industry', 'percent', 'indiabudget', array['mod-ddp']::text[], 'defence', 0, null, 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('defence.milex.usd', 'Military expenditure', 'usd', 'worldbank-wdi', array['sipri-milex']::text[], 'defence', null, 'On SIPRI''s definition — which includes pensions and paramilitary forces — India is the world''s fifth-largest military spender. That definition is deliberately broader than the Ministry of Defence budget line, so this figure is larger than the Indian budget total for the same year.', 'worldbank', 'MS.MIL.XPND.CD', 'IND', 1, 1995, 'transcribed', '2026-07-28'),
  ('defence.milex.gdp-share', 'Military expenditure', 'percent', 'worldbank-wdi', array['sipri-milex']::text[], 'defence', null, 'As a share of the economy, Indian defence spending has been drifting downwards for two decades even as the absolute amount has risen sharply. Growth, not restraint, is doing most of that work.', 'worldbank', 'MS.MIL.XPND.GD.ZS', 'IND', 1, 1995, 'transcribed', '2026-07-28'),
  ('economy.gross-npa-ratio', 'Gross non-performing assets', 'percent', 'rbi-fsr', '{}'::text[], 'economy', null, 'Scheduled commercial banks. The 2015–18 rise is mostly recognition — the RBI''s Asset Quality Review forcing banks to admit loans they had been rolling over — rather than new lending going bad. The fall since is part genuine recovery and part write-off.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('economy.capital-expenditure', 'Union government capital expenditure', 'inr-lakh-crore', 'indiabudget', '{}'::text[], 'economy', null, 'Budget documents; the last two years are Budget Estimates rather than Actuals. Capital spending has roughly trebled in six years, which is the single largest deliberate change in the composition of Union spending in the reform era.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('economy.electronics-exports', 'Electronics exports', 'usd-billion', 'commerce-tradestat', array['pib']::text[], 'economy', 1, 'The clearest single result claimed for the production-linked incentive schemes. Most of the value is smartphone assembly, where imported content remains high — the export figure is gross, not value added in India.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('economy.fdi-inflows', 'Foreign direct investment, net inflows', 'usd', 'worldbank-wdi', array['dpiit-fdi']::text[], 'economy', null, 'Net inflows, which subtract repatriation and disinvestment. Gross inflows have held up far better than the net series; cumulative FDI into India passed $1 trillion during 2025. Both facts belong in the same paragraph.', 'worldbank', 'BX.KLT.DINV.CD.WD', 'IND', 1, 2000, 'transcribed', '2026-07-28'),
  ('economy.forex-reserves', 'Foreign exchange reserves', 'usd', 'worldbank-wdi', array['rbi-dbie']::text[], 'economy', null, 'Reserves peaked above $700 billion during 2024. India holds the fourth-largest stock in the world — roughly eleven months of imports, against the three months conventionally treated as adequate.', 'worldbank', 'FI.RES.TOTL.CD', 'IND', 1, 2000, 'transcribed', '2026-07-28'),
  ('economy.gst-collections', 'Gross GST collections', 'inr-lakh-crore', 'gst-council', array['pib']::text[], 'economy', null, 'Gross collections, all components. Because GST replaced a stack of central and state levies, this series cannot be compared with pre-2017 indirect tax receipts, and it rises with inflation and compliance as well as with real activity.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('economy.ibc-resolutions', 'Resolution plans approved (cumulative)', 'count', 'ibbi', '{}'::text[], 'economy', 0, 'The 2016 insolvency code replaced a system in which recovering money from a failed company took, on average, more than four years. Resolution is still slow against the code''s own 330-day limit, and realisation averages roughly a third of admitted claims.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('economy.income-tax-returns', 'Income tax returns filed', 'count', 'economic-survey', array['pib']::text[], 'economy', null, 'Filing a return is not the same as paying tax: a large share of filers fall below the taxable threshold. The series measures the widening of the formal tax net, not the revenue it yields.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('economy.cpi-inflation', 'Consumer price inflation', 'percent', 'worldbank-wdi', array['mospi-cpi', 'rbi-dbie']::text[], 'economy', null, 'India adopted a formal inflation target in 2016: 4 per cent, with a tolerance band of two points either side. The series before and after that date is the clearest natural experiment in recent Indian macroeconomic policy.', 'worldbank', 'FP.CPI.TOTL.ZG', 'IND', 1, 2005, 'transcribed', '2026-07-28'),
  ('economy.national-highways', 'National highway network', 'km', 'morth', '{}'::text[], 'economy', null, null, 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('economy.upi-transactions', 'UPI transactions', 'billion', 'npci', '{}'::text[], 'economy', 1, 'Transactions per financial year, in billions. UPI now settles more retail payment instructions than any comparable system anywhere; average ticket size is small and falling, so volume growth substantially outpaces value growth.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.case-pendency', 'Cases pending, all courts', 'count', 'njdg', '{}'::text[], 'law', null, 'District courts, high courts and the Supreme Court combined, from the National Judicial Data Grid. Part of the rise is digitisation bringing older cases onto the grid for the first time, which is why this series should be read as a floor.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.conviction-rate', 'Conviction rate, penal code offences', 'percent', 'ncrb-cii', '{}'::text[], 'law', null, null, 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.crimes-against-women', 'Crimes against women, rate', 'per-lakh', 'ncrb-cii', '{}'::text[], 'law', null, 'Per 100,000 women. This series is the sharpest illustration of the reporting problem on the whole site: successive surveys find that most such crimes are never reported at all, so a rising recorded rate is at least partly women being more willing, and police more obliged, to register a case.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.cybercrime-cases', 'Cybercrime cases registered', 'count', 'ncrb-cii', array['mha-i4c']::text[], 'law', 0, 'The fastest-growing recorded offence category in India. Separately, the national cybercrime reporting portal logged financial-fraud complaints running into tens of thousands of crores of rupees in 2024 — complaints, not adjudicated losses.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.homicide-comparison', 'Intentional homicide rate', 'per-lakh', 'unodc', '{}'::text[], 'law', 1, 'UNODC applies a common definition that is slightly wider than the Indian penal code''s "murder", which is why India''s figure here is above the 2.1 the National Crime Records Bureau publishes. Comparing the two directly would be an error.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.murder-count', 'Murders recorded', 'count', 'ncrb-cii', '{}'::text[], 'law', 0, 'Murder is the one offence that is comparable over time and across countries, because a body is hard not to record. India''s count has fallen while its population has grown by well over a hundred million.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.murder-rate', 'Murder rate', 'per-lakh', 'ncrb-cii', '{}'::text[], 'law', 1, null, 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.police-per-lakh', 'Police personnel in position', 'per-lakh', 'bprd', '{}'::text[], 'law', null, 'Against a sanctioned strength of roughly 195 per 100,000 and a frequently-cited United Nations benchmark of 222. Around a fifth of sanctioned posts sit vacant, which is the binding constraint behind most of the numbers in this chapter.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.prison-occupancy', 'Prison occupancy rate', 'percent', 'ncrb-psi', '{}'::text[], 'law', null, null, 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.cognizable-crime-rate', 'Cognizable crime rate', 'per-lakh', 'ncrb-cii', '{}'::text[], 'law', null, 'All cognizable offences, under both the penal code and special laws, per 100,000 people. Recorded crime is a measure of what reaches a police station; it is shaped by willingness to report and by whether the station registers the complaint.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28'),
  ('law.undertrial-share', 'Inmates awaiting trial', 'percent', 'ncrb-psi', '{}'::text[], 'law', null, 'Three out of four people in an Indian prison have not been convicted of anything. This is the number that most directly measures how the justice system treats the people passing through it.', 'manual', null, 'IND', 1, null, 'transcribed', '2026-07-28')
on conflict (id) do update set
  label            = excluded.label,
  unit             = excluded.unit,
  source_id        = excluded.source_id,
  also_source_ids  = excluded.also_source_ids,
  chapter_id       = excluded.chapter_id,
  precision        = excluded.precision,
  note             = excluded.note,
  provider         = excluded.provider,
  indicator_code   = excluded.indicator_code,
  country_code     = excluded.country_code,
  value_scale      = excluded.value_scale,
  period_from      = excluded.period_from,
  transcribed_as_of = excluded.transcribed_as_of;
